package com.prakash.gmcemp.reporting.model;import jakarta.persistence.*;import java.time.*;@Entity public class ReportAudit{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;private String reportType;private LocalDateTime generatedAt;public ReportAudit(){}public ReportAudit(String t){reportType=t;generatedAt=LocalDateTime.now();}public Long getId(){return id;}public String getReportType(){return reportType;}public LocalDateTime getGeneratedAt(){return generatedAt;}}